pub fn displayUniformBlockSlot(ub_name: []const u8) ?usize {
    if (std.mem.eql(u8, ub_name, "display_vs_params")) {
        return 0;
    }
    if (std.mem.eql(u8, ub_name, "display_fs_params")) {
        return 1;
    }
    return null;
}
pub fn displayUniformBlockSize(ub_name: []const u8) ?usize {
    if (std.mem.eql(u8, ub_name, "display_vs_params")) {
        return @sizeOf(DisplayVsParams);
    }
    if (std.mem.eql(u8, ub_name, "display_fs_params")) {
        return @sizeOf(DisplayFsParams);
    }
    return null;
}
pub fn displayUniformOffset(ub_name: []const u8, u_name: []const u8) ?usize {
    if (std.mem.eql(u8, ub_name, "display_vs_params")) {
        if (std.mem.eql(u8, u_name, "view_projection")) {
            return 0;
        }
        if (std.mem.eql(u8, u_name, "light_view_projection")) {
            return 64;
        }
    }
    if (std.mem.eql(u8, ub_name, "display_fs_params")) {
        if (std.mem.eql(u8, u_name, "light_direction")) {
            return 0;
        }
        if (std.mem.eql(u8, u_name, "eye_position")) {
            return 16;
        }
    }
    return null;
}
pub fn displayUniformDesc(ub_name: []const u8, u_name: []const u8) ?sg.GlslShaderUniform {
    if (std.mem.eql(u8, ub_name, "display_vs_params")) {
        if (std.mem.eql(u8, u_name, "view_projection")) {
            var desc: sg.GlslShaderUniform = .{};
            desc.type = .MAT4;
            desc.array_count = 0;
            desc.glsl_name = "view_projection";
            return desc;
        }
        if (std.mem.eql(u8, u_name, "light_view_projection")) {
            var desc: sg.GlslShaderUniform = .{};
            desc.type = .MAT4;
            desc.array_count = 0;
            desc.glsl_name = "light_view_projection";
            return desc;
        }
    }
    if (std.mem.eql(u8, ub_name, "display_fs_params")) {
        if (std.mem.eql(u8, u_name, "light_direction")) {
            var desc: sg.GlslShaderUniform = .{};
            desc.type = .FLOAT3;
            desc.array_count = 0;
            desc.glsl_name = "light_direction";
            return desc;
        }
        if (std.mem.eql(u8, u_name, "eye_position")) {
            var desc: sg.GlslShaderUniform = .{};
            desc.type = .FLOAT3;
            desc.array_count = 0;
            desc.glsl_name = "eye_position";
            return desc;
        }
    }
    return null;
}
